package com.bank.platform.service;

import com.bank.platform.model.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class PricingService {
    private static final Logger log = Logger.getLogger(PricingService.class.getName());

    // LOOM: one virtual thread per task — cheap even at massive scale.
    public Map<String, BigDecimal> priceAll(List<Instrument> instruments) throws InterruptedException {
        var results = new ConcurrentHashMap<String, BigDecimal>();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (Instrument ins : instruments) {
                executor.submit(() -> results.put(ins.symbol(), price(ins)));
            }
        } // executor close() waits for all virtual threads to finish
        return results;
    }

    // AMBER: pattern-matching switch over a sealed type is exhaustive (no default needed).
    private BigDecimal price(Instrument ins) {
        return switch (ins) {
            case Equity e -> e.lastPrice().multiply(new BigDecimal("1.001")); // tiny spread
            case FxPair f -> f.rate().multiply(new BigDecimal("100000"));     // notional
        };
        // VALHALLA (future): if Money were a value class, arrays of prices would
        // flatten with no boxing. PANAMA (future): a risk loop here could use the
        // Vector API for SIMD, or call a native C pricer via the Foreign Function API.
    }
}
