package com.bank.platform;

import com.bank.platform.model.*;
import com.bank.platform.service.PricingService;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ProjectsDemo {
    private static final Logger log = Logger.getLogger(ProjectsDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        List<Instrument> book = List.of(
                new Equity("RELIANCE", new BigDecimal("2450.00")),  // Rajesh trades equities
                new FxPair("USDINR", new BigDecimal("83.10"))       // Priya trades FX
        );
        var pricing = new PricingService();
        Map<String, BigDecimal> priced = pricing.priceAll(book);
        priced.forEach((sym, px) -> log.info(() -> "Priced " + sym + " = Rs." + px));
        // LEYDEN (future): AOT + CDS would make this process start in a few ms,
        // ideal for a serverless pricing function invoked per request.
    }
}
